import pdfplumber, re, pandas as pd
from difflib import SequenceMatcher
from decimal import Decimal
import json

vendors=pd.read_excel('/root/vendors.xlsx')
po=pd.read_csv('/root/purchase_orders.csv')

suffixes={'ltd','limited','inc','incorporated','corp','corporation','llc','gmbh','ag','plc','co','company'}

def normalize(name):
    if name is None: return ''
    s=name.lower()
    s=re.sub(r'[^a-z0-9\s]', ' ', s)
    tokens=[t for t in s.split() if t not in suffixes]
    return ' '.join(tokens)

vendors['norm']=vendors['name'].map(normalize)

norm_to_rows={}
for _,row in vendors.iterrows():
    norm_to_rows.setdefault(row['norm'], []).append(row)


def find_vendor(name):
    norm=normalize(name)
    if norm in norm_to_rows:
        rows=norm_to_rows[norm]
        if len(rows)==1:
            return rows[0]
        best=None; best_score=-1
        for r in rows:
            score=SequenceMatcher(None, name.lower(), str(r['name']).lower()).ratio()
            if score>best_score:
                best_score=score; best=r
        return best
    best=None; best_score=0
    for vnorm,rows in norm_to_rows.items():
        score=SequenceMatcher(None, norm, vnorm).ratio()
        if score>best_score:
            best_score=score; best=rows[0]
    if best_score>=0.85:
        return best
    return None

po_map={row['po_number']: row for _,row in po.iterrows()}

pattern=re.compile(r"From:\s*(.*?)\s*Total\s*\$([0-9.,]+)\s*Payment\s*IBAN:\s*([^\s]+)\s*PO\s*Number:\s*(\S+)")

frauds=[]

with pdfplumber.open('/root/invoices.pdf') as pdf:
    for page_num, page in enumerate(pdf.pages, start=1):
        text=page.extract_text() or ''
        m=pattern.search(text)
        if not m:
            continue
        vendor_name, amount_str, iban, po_number = m.groups()
        amt=Decimal(amount_str.replace(',','')).quantize(Decimal('0.01'))

        vendor_row=find_vendor(vendor_name)
        if vendor_row is None:
            reason='Unknown Vendor'
            po_out=None if po_number=='' else po_number
        else:
            if str(vendor_row['iban']).strip() != str(iban).strip():
                reason='IBAN Mismatch'
                po_out=None if po_number=='' else po_number
            else:
                po_row=po_map.get(po_number)
                if po_row is None:
                    reason='Invalid PO'
                    po_out=None if po_number=='' else po_number
                else:
                    po_amount=Decimal(str(po_row['amount'])).quantize(Decimal('0.01'))
                    if (amt - po_amount).copy_abs() > Decimal('0.01'):
                        reason='Amount Mismatch'
                        po_out=po_number
                    elif str(po_row['vendor_id']).strip() != str(vendor_row['id']).strip():
                        reason='Vendor Mismatch'
                        po_out=po_number
                    else:
                        reason=None
                        po_out=po_number
        if reason:
            frauds.append({
                'invoice_page_number': page_num,
                'vendor_name': vendor_name,
                'invoice_amount': float(amt),
                'iban': iban,
                'po_number': po_out,
                'reason': reason,
            })

with open('/root/fraud_report.json','w', encoding='utf-8') as f:
    json.dump(frauds, f, indent=2)

print('fraud count', len(frauds))
